import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"VABench: A Comprehensive Benchmark for Audio-Video Generation","description":"","frontmatter":{"title":"VABench: A Comprehensive Benchmark for Audio-Video Generation","arxiv":"2512.09299","date":"2025-12-10","authors":"Daili Hua, Xizhi Wang, Bohan Zeng, Xinyi Huang, Hao Liang, Junbo Niu, Xinlong Chen, Quanqing Xu, Wentao Zhang","categories":"cs.CV, cs.SD","topics":"音视频联合生成, 评测基准, 物理声学一致性","outline":[2,2]},"headers":[],"relativePath":"papers/2512.09299.md","filePath":"papers/2512.09299.md","lastUpdated":null}'),p={name:"papers/2512.09299.md"};function l(i,s,r,o,m,c){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="vabench-a-comprehensive-benchmark-for-audio-video-generation" tabindex="-1">VABench: A Comprehensive Benchmark for Audio-Video Generation <a class="header-anchor" href="#vabench-a-comprehensive-benchmark-for-audio-video-generation" aria-label="Permalink to &quot;VABench: A Comprehensive Benchmark for Audio-Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2512.09299" target="_blank" rel="noreferrer">2512.09299</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-12-10</td></tr><tr><td><strong>作者</strong></td><td>Daili Hua, Xizhi Wang, Bohan Zeng, Xinyi Huang, Hao Liang, Junbo Niu, Xinlong Chen, Quanqing Xu, Wentao Zhang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.SD</td></tr><tr><td><strong>一句话</strong></td><td>把带声视频生成拆成 15 个无参考指标（8 个专家模型 + 7 个 MLLM 评分）、7 类内容与立体声专项，量化模型在语义、同步、物理真实三者之间的取舍。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>Veo 3、Sora 2、Wan 2.5 这一代模型已经能同时吐出画面和与之同步的声音，但评测体系还停在纯视觉时代。VBench 和 VBench-2.0 衡量帧质量、时序一致性乃至物理合理性，却没有任何机制去检查声音与画面是否讲同一件事。这不是补一个指标就能解决的缺口：音视频联合生成引入了一批只在跨模态耦合时才出现的现象——运动物体的多普勒频移、闪电与雷声的先后次序、人物情绪在语音语调和面部表情上的协同、背景音乐与画面剪辑节奏的对齐。这些恰恰是&quot;世界模型&quot;叙事最想宣称的能力，却没有可量化的证据。VABench 的目标是把这块空白补上：给出一套无参考（reference-free）、可自动运行、且经过人类偏好校准的评测框架。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文明确点名了三类前人工作。第一类是纯视觉 benchmark：VBench、VBench-2.0、Evaluation Agent，它们把 FVD、IS 这类单一分数换成了多维框架，覆盖到帧级质量和高阶真实性，但完全缺少跨模态一致性的测量手段。第二类是 V2A 方向的评测集，如 BRACE 和 MMAudio 一脉的工作，它们大多是 reference-based，需要真实的视频-音频配对作为 ground truth；这在 T2AV 场景下直接失效，因为文本到音视频的生成没有唯一正确答案，需要的是文本、视频、音频三角一致性的无参考度量。第三类是已有的联合评测尝试，JavisBench/JAVISDiT 做了探索，但维度有限、场景受限，尤其缺少对物理耦合与情绪耦合这类高阶关系的量化。还有一类隐性缺口：Movie Gen 一类工作依赖人工打分，质量高但不可扩展。此外几乎所有 AV 模型都输出立体声，却没有任何 benchmark 去测空间声像。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>如果只能靠已有知识出发，一个认真的研究者大概会这样走。先承认一个事实：AV 模型输出的是一段完整成品，没有配对的真值可比，所以任何 reference-based 指标都不可用，评测必须是&quot;给定条件、检查输出是否满足条件&quot;的形式。接着问：条件里有哪些可检验的成分？文本里既有视觉要素也有听觉要素，那就用 LLM 把 prompt 结构化拆成视觉子提示和听觉子提示。再问：哪些性质有现成的专家模型能可靠打分？语音质量有 DNSMOS/NISQA，音频美学有 Audiobox，跨模态相似度有 ViCLIP/CLAP/ImageBind，时序对齐有 Synchformer 和 SyncNet 系。剩下那些没有专家模型的东西——物理合理性、情绪表达、艺术性——只能靠人，但人不可扩展，于是转向 Omni-modal LLM 做代理，并且必须回过头验证它与人类判断相关。最后一步是承认粗粒度打分容易被&quot;看起来不错&quot;糊弄，所以再补一层细粒度：为每条样本生成 3–7 个针对具体声音细节的问答，逐题判对错。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>音视频生成的失败不发生在&quot;画面糊&quot;或&quot;声音噪&quot;，而发生在两条模态各自说得通、合在一起说不通。所以评测的核心不是提升单模态分数的精度，而是构造出足够多&quot;必须两边同时正确才能通过&quot;的检查点——细粒度 QA、同步偏移、唇音一致、声像方位。把这些检查点按内容类别铺开，模型的短板就会自己暴露出来。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>数据端用双路策略：T2AV 共 778 条样本，I2AV 共 521 条，立体声用 116 条明确指定左右声源的 prompt。以一条 T2AV 样本为例：先用专家模板加 LLM 批量生成原始 prompt（如&quot;黎明住宅区街道，远处第一班公交引擎轰鸣，鸟鸣清脆，送奶工把玻璃瓶放进门口筐里发出轻碰声，慢跑者跑过发出节奏性脚步声&quot;），再由 LLM 把它解耦成视觉子提示与听觉子提示，同时生成对应的 VQA 与 AQA 问答对，最后人工核验类别归属、要素可观测性以及是否违反物理常识。I2AV 路则先人工筛选高质图片并剔除隐私内容，用 MLLM 生成统一的音视描述，再拆解成子提示与问答。</p><p>评测端分两轨。专家模型轨给出 8 个指标：SpeechClarity（DNSMOS OVRL）、SpeechQual&amp;Nat（NISQAv2）、AudioAesthetic（Audiobox 四维聚合）、Text-Video Align（ViCLIP）、Text-Audio Align（CLAP）、Audio-Visual Align（ImageBind）、Desync（Synchformer，取首尾各 4.8 秒窗口）、Lip-Sync（仅用于检测到说话人头部的人类语言子集）。MLLM 轨用 Qwen2.5-Omni-7B，宏观层给 Alignment、Artistry、Expressiveness、Audio Realism、Visual Realism 五个 1–5 分维度（真实性两项排除虚拟世界类别），微观层跑逐题问答。立体声另算 9 个声学量：Mid/Side 能量比表征声场宽度、ITD 波动表征声像稳定性、ILD 波动表征电平稳定性、包络相关与瞬态同步表征通道一致性，以及低中高三频段相位相干和单声道下混兼容度。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文的形式化不多，但两个聚合式值得说清。音频美学分把 Audiobox 的四个子维度合成一个&quot;越高越好&quot;的量，其中制作复杂度 PC 被减去，依据是既有工作观察到 PC 与感知质量负相关：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">audio-aesthetic</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">4</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>细粒度 QA 分则是逐样本的准确率再取平均。设测试集有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 条样本，第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 条生成了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 个细节问题，其中被判定为满足的有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 个：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>这里用样本内准确率再平均、而不是把所有问题混在一起算全局准确率，效果是让问题数多的样本不会主导整体分数。这个选择在论文里没有解释，可以推断是为了让类别间的对比不被题量分布污染。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>被测系统分两类：端到端 AV 模型（Veo3-fast、Wan2.5 Preview、Sora2）与解耦的 V+A 组合（视频侧 Seedance-1.0-Lite / Wan2.2-TI2V / Kling2.5-Turbo，音频侧 MMAudio / ThinkSound light）。</p><p>问题一：端到端联合训练是否真的优于拼装？答案是基本成立。T2AV 上 AV 模型整体领先，AQA 分析里&quot;即便最强的 V+A 组合也没超过最弱的 AV 模型&quot;；I2AV 因为图像输入提供了强视觉约束，模型间差距被压缩，Seedance+MMAudio 在 Alignment 上甚至反超部分 AV 模型。</p><p>问题二：语义、同步、真实性能否兼得？不能。Veo3 在音频质量与跨模态语义对齐上最强，Sora2 真实性突出但音频美学与同步落后，Wan2.5 同步（尤其 Lip-Sync）最好但语义对齐略低。这是全文最有价值的结论之一。</p><p>问题三：哪些内容类别是硬骨头？Music 在两个任务上都最容易，作者归因于音乐音频与视觉动态之间天然的相关性；Human Sounds 与 Complex Scenes 一致垫底，前者卡在毫秒级唇同步与抽象状态（如&quot;沉思&quot;）的表达，后者卡在多源融合与场景推理。</p><p>问题四：立体声真的做出来了吗？没有。人工核验显示三个模型都无法从文本可靠地生成语义化的左右分离：Wan2.5 左右声道相关度 0.9998，本质是单声道；Sora2 声场最宽但宽度来自相位偏移，声源定位不稳；Veo3 声像最稳定，偶尔在自然场景中产生随画面运动的空间声源。作者据此推断 Veo3 与 Sora2 的训练数据中存在空间音频线索。</p><p>问题五：这套自动分数可信吗？6 位专业评测者对三个模型的代表性子集按语义、同步、真实性三维打分，转成两两胜率后与 VABench 聚合分做 Pearson 相关，各维度均呈强相关。样本规模偏小，作者自己称之为 pilot study。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：VABench 把带声视频生成的评测从单模态质量推进到跨模态耦合，覆盖 T2AV、I2AV 与立体声三类任务、7 大内容类别、15 个无参考指标。指标分两轨，专家模型负责可精确测量的量（语音质量、跨模态相似度、同步偏移），Omni-modal LLM 负责需要判断的量（物理真实、情绪表达、细粒度事件问答）。实验显示端到端 AV 模型系统性优于视频模型加 V2A 的拼装方案，但语义、同步、真实性三者仍无法同时达标。人类声音与复杂场景是所有系统的共同瓶颈，音乐是共同强项。所有被测模型都无法按文本指令生成语义正确的立体声分离。</p><p><strong>3 句话版</strong>：这是第一个把物理声学耦合、情绪协同和立体声空间感纳入量化的音视频生成 benchmark。它用专家模型加 MLLM 双轨、宏观打分加细粒度 QA 双层的设计换取了无参考与可扩展性。结论是端到端联合建模有结构性优势，但三角权衡与人声、复杂场景、立体声三个瓶颈仍未被解决。</p><p><strong>1 句话版</strong>：给&quot;能出声的视频模型&quot;造了一把能同时量语义、同步和物理真实的尺子，量出来的结果是三者还没人能兼得。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的假设是：Qwen2.5-Omni-7B 作为评测者，在&quot;物理真实性&quot;和&quot;细粒度音频事件是否存在&quot;这两件事上的判断可靠到足以给前沿模型排序。7 个指标里有 7 个依赖它，包括论文最看重的 Audio QA / Visual QA。这个假设脆弱在于，判断&quot;雷声是否在闪电之后&quot;或&quot;玻璃瓶碰撞声是否出现&quot;要求评测模型自己具备可靠的音频事件检测与时序推理能力，而这恰恰是当前 Omni 模型最不稳的部分——它很可能因为 prompt 里提到了某个声音就倾向于回答&quot;听到了&quot;。论文提供的证据是一次 pilot user study，6 位评测者、3 个模型、代表性子集，报告了 Pearson 相关系数强；但这个校准是在聚合后的三个粗维度（语义、同步、真实）上做的，并没有直接验证逐题 QA 判定的准确率。缺的正是这一块：把 MLLM 的逐题判定与人工逐题标注对齐，报告题级一致率。若 MLLM 存在系统性的&quot;顺从 prompt&quot;偏置，所有类别排名都会向&quot;prompt 写得越细分越高&quot;倾斜，而这与生成质量无关。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的最小验证只针对上面那个假设，不必复现整套 benchmark。取 60 条 T2AV 样本，每条从公开可调用的两个模型各生成一段（一个 AV 模型、一个 V+A 组合），共 120 段。对每段沿用论文的 3–7 题 QA 协议，同时做两件事：一是让 Qwen2.5-Omni-7B 按论文 prompt 判定，二是请 3 位标注者独立逐题判定并取多数。测量题级一致率与 Cohen&#39;s kappa，并按问题类型分层（声音存在性 / 时序先后 / 材质音色 / 空间方位）。再加一组对照：把音频轨替换成与画面无关的随机音频，看 MLLM 的&quot;Yes&quot;率下降多少。若整体 kappa 高于 0.6 且随机音频对照下 Yes 率显著崩塌，支持论文的评测可靠性；若 kappa 低于 0.4，或随机音频仍能拿到接近的分数，则说明 QA 分主要反映的是 prompt 措辞而非生成内容，论文的类别排名需要重新解读。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是给出一个替代解释：AV 模型对 V+A 模型的全面领先，可能不是&quot;端到端联合训练捕捉跨模态协同&quot;，而是视频侧基础能力差距 + 输出规格差异造成的假象。证据线索就在论文自己的表里——Sora2 默认输出 10 秒 30 FPS，Veo3-fast 8 秒 24 FPS，其余均为 5 秒 24 FPS。时长直接影响 Desync 的窗口覆盖、细粒度 QA 中&quot;事件是否出现&quot;的机会，以及 MLLM 对叙事表达力的观感。同时 Veo3 与 Sora2 的视频塔本身就比 Seedance-Lite、Wan2.2-TI2V 强一个档次，而论文自己观察到&quot;更高质量的视频生成能提升音频生成潜力&quot;（Kling+MMAudio 成为最强 V+A 就是这条规律的体现）。把两条线索合起来，就有了一个不需要&quot;联合训练优势&quot;的完整解释。构造反例的做法是控制变量：把所有输出统一裁剪到 5 秒 24 FPS 重新评分，并把 V+A 的视频侧换成与 Veo3 视频质量相当的模型，再看 AV 与 V+A 的差距还剩多少。如果差距大幅收窄，论文最核心的架构学结论就失去支撑。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：VABench 用打分回答&quot;像不像&quot;，但物理耦合本质上是可测量的——多普勒频移量由相对速度决定，雷声延迟由距离决定，混响时间由空间尺寸决定，声压随距离按平方反比衰减。用 1–5 分去评价这些，等于把可解析的物理量降级成主观印象。</p><p><strong>新 framing</strong>：把音视频评测从&quot;打分&quot;改成&quot;参数反演&quot;。给定一段生成视频，从画面用现成的单目深度与光流估计物体的相对速度和距离轨迹，从音频用信号处理反解出频移曲线、事件延迟、衰减斜率与混响时间，然后检验两条独立通路给出的物理参数是否一致。指标不再是模型给的分数，而是物理参数的相对误差。</p><p><strong>可借鉴的相邻领域工具</strong>：声源定位与房间声学的经典方法（ITD/ILD 反演、RT60 估计、图像声源法）、音视频自监督对应学习里的时序对齐技术，以及机器人领域用于系统辨识的参数估计框架。</p><p><strong>第一个实验</strong>：构造一组只含单一运动声源的受控 prompt（车辆驶过、直升机掠过、球体落地），每条 prompt 明确指定速度或高度。生成视频后，从画面测出声源在图像平面的位移速率，从频谱提取基频轨迹并按多普勒公式反解速度，报告两者的相对误差分布。成功的判据是误差随 prompt 指定速度单调、且方差可控；失败的判据是模型只是在&quot;声音渐弱&quot;层面模仿，频移与画面速度不相关——那就说明当前模型学到的是声学的表面统计，而非物理关系。</p>',42)])])}const d=a(p,[["render",l]]);export{g as __pageData,d as default};
